/*
 * One row per learner, sorted by name: who they are and where their plan stands.
 * The templates ride along because the Add learner form on the same page offers
 * them, and two calls for one page would be two ways to fail. Archived templates
 * are not offered (DBU-04).
 */
(async () => {
  try {
    const ids = Array.isArray(Inputs.userIds) ? Inputs.userIds.map(String) : [];
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
    const users = ids.length ? await q('_User', { objectId: { containedIn: ids } }) : [];
    const plans = ids.length ? await q('Plan', { learner: { containedIn: ids } }) : [];
    const steps = ids.length ? await q('Step', { learner: { containedIn: ids } }) : [];
    const finished = ['done', 'approved', 'missed'];

    Outputs.learners = users
      .map((u) => {
        const mine = plans.filter((p) => p.learner === u.objectId);
        const plan = mine.find((p) => p.status === 'active') || mine.sort((a, b) => String(b.startedOn).localeCompare(String(a.startedOn)))[0] || null;
        const planSteps = plan ? steps.filter((s) => s.plan === plan.objectId) : [];
        return {
          id: u.objectId,
          name: u.name || u.email,
          email: u.email,
          organisation: u.organisation || '',
          jobTitle: u.jobTitle || '',
          lastSeenAt: u.lastSeenAt || null,
          planTitle: plan ? plan.title : '',
          planStatus: plan ? plan.status : '',
          steps: planSteps.length,
          shared: planSteps.filter((s) => s.shared === true).length,
          finished: planSteps.filter((s) => finished.includes(s.status)).length
        };
      })
      .sort((a, b) => a.name.localeCompare(b.name));
    Outputs.templates = (await q('PlanTemplate', {}))
      .filter((t) => t.archived !== true)
      .map((t) => ({ id: t.objectId, title: t.title }))
      .sort((a, b) => a.title.localeCompare(b.title));
    Outputs.done();
  } catch (e) {
    console.error('[dbu:roster]', String((e && e.message) || e));
    Outputs.failed();
  }
})();

// DBU-07: how many of each learner's messages nobody on staff has read yet, for the roster row.
// DBU-09: and how many creations each learner keeps.
(async () => {
  try {
    const rows = Array.isArray(Inputs.learners) ? Inputs.learners : [];
    const waiting = await Noodl.Records.query('Message', { readAt: { exists: false } }, { limit: 1000, plain: true });
    const ids = rows.map((l) => l.id);
    const made = ids.length ? await Noodl.Records.query('Creation', { learner: { containedIn: ids } }, { limit: 1000, plain: true }) : [];
    Outputs.learners = rows.map((l) => Object.assign({}, l, {
      unread: waiting.filter((m) => m.learner === l.id && m.author === m.learner && !m.readAt).length,
      creations: made.filter((c) => c.learner === l.id).length
    }));
    Outputs.done();
  } catch (e) {
    console.error('[dbu:roster unread]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
